useEffect(()=>{let cancelled=false;const term=normalizeSearch(search).trim();if(!term||term.length<2||!activeCondoId||!supabase){GR([]);GS(false);return;}GS(true);const timer=window.setTimeout(async()=>{const sources=[['units','apartments'],['residents','apartment_residents'],['family','unit_family_members'],['pets','unit_pets'],['authorized_visitors','authorized_visitors'],['packages','packages'],['visitors','visitor_logs'],['reservations','reservations'],['occurrences','occurrences'],['announcements','announcements'],['documents','documents'],['vehicles','vehicles'],['common_areas','common_areas'],['parking','parking_spaces'],['bicycle_assets','bicycle_assets'],['bicycle_keys','bicycle_keys'],['bicycle_movements','bicycle_key_movements'],['finance','financial_transactions'],['finance','financial_documents'],['activity','resident_notifications']];const terms=term.split(' ').filter(Boolean);const batches=await Promise.all(sources.map(async(source)=>{const pageKey=source[0],tableName=source[1];try{let query:any=supabase!.from(tableName).select('*');if(tableName==='apartment_residents')query=supabase!.from(tableName).select('*,profiles(full_name,email,phone,avatar_url),apartments(block,floor,number)');else if(tableName==='apartments')query=supabase!.from(tableName).select('*,apartment_residents(resident_type,profiles(full_name,email,phone))');else if(['unit_family_members','unit_pets','authorized_visitors','visitor_logs','documents','vehicles'].includes(tableName))query=supabase!.from(tableName).select('*,apartments(block,floor,number)');else if(tableName==='reservations')query=supabase!.from(tableName).select('*,common_areas!reservations_area_id_fkey(name,area_type),apartments!reservations_apartment_id_fkey(block,number)');else if(tableName==='parking_spaces')query=supabase!.from(tableName).select('*,apartments(block,number),vehicles(plate,make,model)');else if(tableName==='bicycle_key_movements')query=supabase!.from(tableName).select('*,bicycle_keys(key_code),apartments(block,number)');const result=await query.eq('condominium_id',activeCondoId).limit(400);if(result.error)return [];const matched=(result.data||[]).filter((row:R)=>{const hay=normalizeSearch(JSON.stringify(row));return terms.every(t=>hay.includes(t));}).slice(0,3);return Promise.all(matched.map(async(row:R)=>{if(tableName==='apartment_residents'&&row.profiles?.avatar_url){const photo=row.profiles.avatar_url;if(photo.startsWith('http://')||photo.startsWith('https://')){}else{const {data:signed}=await supabase!.storage.from('resident-photos').createSignedUrl(photo,3600);row.profiles={...row.profiles,avatar_url:signed?.signedUrl||''};}}return {pageKey,tableName,row};}));}catch{return [];}}));if(cancelled)return;GR(batches.flat().sort((a:R,b:R)=>(a.pageKey==='residents'?0:1)-(b.pageKey==='residents'?0:1)).slice(0,40));GS(false);},350);return()=>{cancelled=true;window.clearTimeout(timer);};},[search,activeCondoId]);

